package world.taqwa.app.prayer.engine.registry.data

/**
 * Diyanet's European method at its own city tables (rulings R39, R42, R44): for each held city north
 * of 44.5° (its takdir), the sun's depression at each printed Fajr and Isha, by R28's slot (the month
 * and day of 2028-01-01 + i), so that its point table starts each prayer where Diyanet prints it,
 * takdir included, rather than at a generic night fraction (up to 39 min late at Fajr and 143 min at
 * Isha before).
 *
 * Derived parameters, not times: at the city's point and under the engine's own daily sun (declination
 * and equation of time once at 0h UT of the date, as the method computes), the depression 25 s before
 * each printed minute (Diyanet rounds to the nearest minute, so its own moment is at most 30 s before
 * it); per slot the smallest such Fajr depression (the latest Fajr) rounded down to a hundredth of a
 * degree, and the largest Isha depression and the largest Fajr depression (the earliest, for the end
 * of eating, which the table prints in the same column) rounded up; 29 February from its neighbours;
 * then each the smallest (Fajr) or largest (Isha, the end) of the day before, the day and the day
 * after, so the leap cycle's drift cannot make a start early or the end late. Source: Diyanet İşleri
 * Başkanlığı's tables for these cities, 25 Sep 2026 – 31 Dec 2027 (namazvakitleri.diyanet.gov.tr;
 * restricted, "all rights reserved"): only these depressions are kept; the tables themselves are
 * not committed.
 */
internal object DiyanetEuropeCurves {
    /** One city's Fajr, Isha and end-of-eating depressions (degrees, by slot) at its point. */
    class Curves(val fajrEncoded: String, val ishaEncoded: String, val endEncoded: String) {
        val fajr: DoubleArray by lazy { decode(fajrEncoded) }
        val isha: DoubleArray by lazy { decode(ishaEncoded) }
        val end: DoubleArray by lazy { decode(endEncoded) }

        private fun decode(s: String) =
            s.trim().split(' ').map { it.toInt() / 100.0 }.toDoubleArray().also { require(it.size == 366) }
    }

